// Which changed files can hold markup, and which of their lines did this merge request add?
// Only added lines can block; everything else in the file is existing debt.
const rules = $('Accessibility Rules').first().json;
const ev = $('Merge Request Opened Or Updated').first().json.body || $('Merge Request Opened Or Updated').first().json;
const exts = String(rules.file_extensions || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const diffs = [];
for (const i of $input.all()) {
  const j = i.json || {};
  if (Array.isArray(j)) diffs.push(...j);
  else if (Array.isArray(j.data)) diffs.push(...j.data);
  else if (j.new_path) diffs.push(j);
  else if (j.error) throw new Error('GitLab did not list the changed files, so nothing was checked: ' + JSON.stringify(j.error).slice(0, 200));
}
const base = {
  project_id: ev.project.id, iid: ev.object_attributes.iid,
  sha: ev.object_attributes.last_commit.id, source_branch: ev.object_attributes.source_branch,
  owner: String(ev.project.path_with_namespace).split('/').slice(0, -1).join('/'),
  repository: String(ev.project.path_with_namespace).split('/').slice(-1)[0],
  labels: (ev.labels || []).map((l) => l.title),
};
const out = [];
for (const d of diffs) {
  if (!d.new_path || d.deleted_file) continue; // an empty listing arrives as one empty item
  const path = String(d.new_path);
  const dot = path.lastIndexOf('.');
  if (!exts.includes(dot >= 0 ? path.slice(dot).toLowerCase() : '')) continue;
  const added = [];
  let line = 0;
  for (const row of String(d.diff || '').split('\n')) {
    const h = row.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (h) { line = Number(h[1]); continue; }
    if (row.startsWith('+')) { added.push(line); line += 1; }
    else if (row.startsWith('-')) continue;
    else if (row.startsWith('\\')) continue;
    else line += 1;
  }
  out.push({ json: Object.assign({ none: false, path, new_file: !!d.new_file, added_lines: added, diff_complete: !d.too_large && !d.collapsed }, base) });
}
if (!out.length) return [{ json: Object.assign({ none: true, path: null, new_file: false, added_lines: [], diff_complete: true }, base) }];
return out;

// Accessibility checks that can be proved from markup alone. Each finding names the WCAG 2.1
// success criterion the EAA points to (through EN 301 549), and whether the merge request added it.
const rules = $('Accessibility Rules').first().json;
const files = $('Keep Web Files And Added Lines').all().map((i) => i.json);
const got = $input.all().map((i) => i.json || {});
const minContrast = Number(rules.min_contrast || 4.5);
const findings = [];
const unread = [];
const whole_files = [];
const hexRgb = (h) => {
  let s = String(h).replace('#', '');
  if (s.length === 3) s = s.split('').map((c) => c + c).join('');
  if (!/^[0-9a-f]{6}$/i.test(s)) return null;
  return [0, 2, 4].map((i) => parseInt(s.slice(i, i + 2), 16) / 255);
};
const lum = (rgb) => { const f = (c) => (c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4)); return 0.2126 * f(rgb[0]) + 0.7152 * f(rgb[1]) + 0.0722 * f(rgb[2]); };
const ratio = (a, b) => { const x = lum(a); const y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const has = (attrs, names) => names.some((n) => new RegExp('(^|\\s)(:|v-bind:)?' + n + '(\\s*=|\\s|$|/)', 'i').test(attrs));
const hasAlt = (attrs) => /(^|\s)(:|v-bind:)?alt\s*=/i.test(attrs) || /(^|\s)alt(\s|$|\/)/i.test(attrs);
const attr = (attrs, n) => { const m = attrs.match(new RegExp('(?:^|\\s)' + n + '\\s*=\\s*("([^"]*)"|\'([^\']*)\'|\\{([^}]*)\\}|([^\\s>]+))', 'i')); return m ? (m[2] ?? m[3] ?? m[4] ?? m[5] ?? '') : null; };
const hidden = (attrs) => /aria-hidden\s*=\s*["']?true/i.test(attrs) || /role\s*=\s*["']?(presentation|none)/i.test(attrs);

files.forEach((f, idx) => {
  if (f.none) return;
  const g = got[idx] || {};
  if (!g.content || g.error) { unread.push({ path: f.path, why: g.error ? JSON.stringify(g.error).slice(0, 120) : 'no content' }); return; }
  const text = Buffer.from(String(g.content), g.encoding === 'base64' ? 'base64' : 'utf8').toString('utf8');
  const lineAt = (i) => text.slice(0, i).split('\n').length;
  const added = new Set(f.added_lines || []);
  // When GitLab truncated or collapsed this file's diff, the added lines are unknown: every problem in it
  // counts as added, so a large change cannot pass by hiding its diff.
  const whole = f.diff_complete === false;
  if (whole) whole_files.push(f.path);
  const add = (i, rule, wcag, level, what, fix) => { const line = lineAt(i); findings.push({ path: f.path, line, rule, wcag, level, what, fix, added: f.new_file || whole || added.has(line) }); };
  const labelled = new Set();
  for (const m of text.matchAll(/<label\b[^>]*?\b(?:for|htmlFor)\s*=\s*["'{]?([\w:-]+)/gi)) labelled.add(m[1]);
  const tagRe = /<([a-zA-Z][\w-]*)(\s[^<>]*?)?\s*(\/)?>/g;
  let m;
  while ((m = tagRe.exec(text))) {
    const tag = m[1].toLowerCase(); const attrs = m[2] || ''; const at = m.index;
    if (tag === 'img' && !hasAlt(attrs) && !hidden(attrs)) add(at, 'img-alt', '1.1.1 Non-text Content', 'error', 'an image has no alt attribute', 'add `alt="what it shows"`, or `alt=""` if it is decoration');
    if (['input', 'select', 'textarea'].includes(tag)) {
      const type = (attr(attrs, 'type') || 'text').toLowerCase();
      if (!['hidden', 'submit', 'button', 'reset', 'image'].includes(type)) {
        const id = attr(attrs, 'id');
        const before = text.slice(0, at); const open = before.lastIndexOf('<label'); const close = before.lastIndexOf('</label');
        const wrapped = open > close;
        if (!has(attrs, ['aria-label', 'aria-labelledby', 'title']) && !(id && labelled.has(id)) && !wrapped) add(at, 'field-label', '1.3.1 Info and Relationships / 4.1.2 Name, Role, Value', 'error', (tag === 'input' ? 'an input' : 'a ' + tag) + ' has no label', 'add a `<label for>` that points to its id, or `aria-label`');
      }
    }
    if (tag === 'html' && !m[3] && attr(attrs, 'lang') === null && attr(attrs, ':lang') === null) add(at, 'html-lang', '3.1.1 Language of Page', 'error', 'the page does not say its language', 'add `lang="en"` (or the page language) to `<html>`');
    if (tag === 'iframe' && !has(attrs, ['title', 'aria-label', 'aria-labelledby']) && !hidden(attrs)) add(at, 'frame-title', '4.1.2 Name, Role, Value', 'error', 'a frame has no title', 'add `title="what the frame shows"`');
    if ((tag === 'button' || (tag === 'a' && attr(attrs, 'href') !== null)) && !m[3] && !has(attrs, ['aria-label', 'aria-labelledby', 'title']) && !hidden(attrs)) {
      const end = text.indexOf('</' + tag, tagRe.lastIndex);
      const inner = end >= 0 ? text.slice(tagRe.lastIndex, end) : '';
      const words = inner.replace(/<img\b[^>]*\balt\s*=\s*["']([^"']+)["'][^>]*>/gi, ' $1 ').replace(/<[^>]*>/g, '').replace(/\{\{[^}]*\}\}|\{[^}]*\}/g, 'x').trim();
      if (!words) add(at, tag === 'a' ? 'link-name' : 'button-name', tag === 'a' ? '2.4.4 Link Purpose / 4.1.2' : '4.1.2 Name, Role, Value', 'error', 'a ' + (tag === 'a' ? 'link' : 'button') + ' has no text a screen reader can say', 'add visible text, or `aria-label`');
    }
    const style = attr(attrs, 'style');
    if (style) {
      const fg = style.match(/(?:^|;)\s*color\s*:\s*(#[0-9a-f]{3,6})\b/i); const bg = style.match(/background(?:-color)?\s*:\s*(#[0-9a-f]{3,6})\b/i);
      if (fg && bg) {
        const a = hexRgb(fg[1]); const b = hexRgb(bg[1]);
        if (a && b) { const r = ratio(a, b); if (r < minContrast) add(at, 'contrast', '1.4.3 Contrast (Minimum)', 'error', 'text contrast is ' + r.toFixed(2) + ':1 (' + fg[1] + ' on ' + bg[1] + '), below ' + minContrast + ':1', 'darken the text or lighten the background'); }
      }
    }
    const tab = attr(attrs, 'tabindex');
    if (tab !== null && Number(tab) > 0) add(at, 'tabindex', '2.4.3 Focus Order', 'warning', 'tabindex=' + tab + ' changes the keyboard order', 'use 0 or -1 and fix the DOM order instead');
    if ((tag === 'video' || tag === 'audio') && /(^|\s)autoplay(\s|=|$)/i.test(attrs)) add(at, 'autoplay', '1.4.2 Audio Control', 'warning', 'media starts playing on its own', 'remove autoplay, or start muted with controls');
  }
});
return [{ json: { findings, unread, whole_files, files_checked: files.filter((f) => !f.none).length - unread.length } }];

// Block only on problems this merge request adds, or on a file that could not be read. Existing
// debt is counted and shown, never blamed. The waiver label turns a block into a recorded pass.
const rules = $('Accessibility Rules').first().json;
const f0 = $('Keep Web Files And Added Lines').first().json;
const r = $input.first().json;
const warnBlocks = rules.block_on_warnings === true;
const added = r.findings.filter((x) => x.added);
const existing = r.findings.filter((x) => !x.added);
const blocking = added.filter((x) => x.level === 'error' || warnBlocks);
const waiver = String(rules.waiver_label || '');
const waived = !!waiver && f0.labels.includes(waiver);
const unreadBlocks = r.unread.length > 0;
const block = (blocking.length > 0 || unreadBlocks) && !waived;
let description;
if (unreadBlocks && !waived) description = r.unread.length + ' changed file(s) could not be read, so they were not checked';
else if (block) description = blocking.length + ' accessibility problem(s) added by this merge request';
else if (waived && (blocking.length || unreadBlocks)) description = 'Waived by label ' + waiver + ': ' + blocking.length + ' problem(s) added';
else if (r.files_checked === 0 && !f0.none) description = 'No changed markup could be checked';
else if (f0.none) description = 'No markup files changed';
else description = 'No accessibility problems added (' + r.files_checked + ' file(s) checked)';
const row = (x) => '| `' + x.path + ':' + x.line + '` | ' + x.what + ' | ' + x.wcag + ' | ' + x.fix + ' |';
const parts = ['<!-- eaa-accessibility-check -->', '### Accessibility check (EU Accessibility Act basics)', '',
  '**' + (block ? 'Blocked' : 'Passed') + ':** ' + description + '. Checked commit ' + String(f0.sha).slice(0, 8) + '.', ''];
if (waived) parts.push('This merge request carries the **' + waiver + '** label, so it is not blocked. Say in the description why, and when it will be fixed.', '');
if (added.length) parts.push('#### Added by this merge request', '', '| where | problem | WCAG 2.1 | fix |', '|---|---|---|---|', ...added.slice(0, 50).map(row), '');
if (added.length > 50) parts.push('...and ' + (added.length - 50) + ' more.', '');
if (r.unread.length) parts.push('#### Not checked', '', ...r.unread.map((u) => '- `' + u.path + '`: ' + u.why), '');
if ((r.whole_files || []).length) parts.push('#### Checked as a whole', '', 'GitLab did not send the full diff for ' + r.whole_files.map((p) => '`' + p + '`').join(', ') + ', so every problem in these files counts as added.', '');
if (existing.length) parts.push('#### Already on the target branch (not blocking)', '', existing.length + ' problem(s) in lines this merge request did not change. Worth a separate clean-up.', '');
parts.push('_Checks markup only: text alternatives, form labels, page language, empty buttons and links, frame titles, inline colour contrast, tabindex, autoplay. It does not replace a review of the rendered page._');
return [{ json: {
  state: block ? 'failed' : 'success', description: description.slice(0, 250), status_name: rules.status_name || 'eaa-accessibility',
  project_id: f0.project_id, iid: f0.iid, sha: f0.sha, blocked: block, waived,
  added_count: added.length, blocking_count: blocking.length, existing_count: existing.length, unread_count: r.unread.length,
  note: parts.join('\n'), worth_a_comment: added.length > 0 || r.unread.length > 0 || waived,
} }];

// Keep ONE comment per merge request: edit it on every push instead of adding a new one. A clean
// first run adds nothing; a run that fixes everything edits the old comment to say so.
const d = $('Decide Pass Or Block').first().json;
const notes = [];
for (const i of $input.all()) { const j = i.json || {}; if (Array.isArray(j)) notes.push(...j); else if (j.id && j.body !== undefined) notes.push(j); }
const ours = notes.find((n) => String(n.body || '').indexOf('<!-- eaa-accessibility-check -->') === 0);
const action = ours ? 'update' : (d.worth_a_comment ? 'post' : 'skip');
return [{ json: { action, note_id: ours ? ours.id : null, project_id: d.project_id, iid: d.iid, note: d.note } }];
